let ssCurrent=null;
const beforeSourceStudio=render;
render=function(){if(location.hash!=='#studio-sources')return beforeSourceStudio();document.getElementById('app').innerHTML=integratedShell('studio-sources',heading('Source Studio','Scholarion Academy · Source-grounded generation and export')+`<section class="card prose"><strong>AI-assisted content.</strong><p>Add sources, map outcomes, then build separate student and instructor drafts. Hosted generation requires a configured model; incomplete artifacts remain visibly blocked.</p><p id="ss-status" role="status">Connecting…</p><label>Course<select id="ss-course"></select></label><form id="ss-create"><label>Module title<input name="title" required maxlength="200"></label><label>Week<input name="module" type="number" min="1" max="10" required></label><button class="button">Create module workspace</button></form><a href="#assignment-packages">Assignment package studio</a></section><div id="ss-list"></div><div id="ss-detail"></div>`,model.role);bind();normalizeWorkspace();ssLoad();};
async function ssLoad(){try{workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';const d=await workspaceApi('studio-sources/list');if(location.hash!=='#studio-sources')return;document.getElementById('ss-course').innerHTML=workspaceSession.courses.map(c=>`<option ${c===selectedCourse?'selected':''}>${esc(c)}</option>`).join('');document.getElementById('ss-list').innerHTML=d.modules.map(m=>`<section class="card prose"><button class="button secondary" data-ss-open="${m.id}">${esc(m.title)} · revision ${m.revision}</button></section>`).join('');document.getElementById('ss-status').textContent='Authorized instructor workspace. Build controls appear below the selected module.';}catch(e){document.getElementById('ss-status').textContent=e.message;}}
function ssShow(d){ssCurrent=d;const p=d.package;document.getElementById('ss-detail').innerHTML=`<section class="card prose"><h2>${esc(p.title)}</h2><p>Revision ${d.revision} · ${p.sources.length} sources</p><ul>${p.sources.map(s=>`<li>${esc(s.id)}: ${esc(s.title)} — citation needs verification</li>`).join('')}</ul><form id="ss-source"><h3>Add source text</h3><p>Use only material you may use. Do not add credentials or personal records. Source instructions are content, not executable commands.</p><label>Source title<input name="title" required maxlength="200"></label><label>Citation or source reference<input name="citation" required maxlength="1000"></label><label>Rights<select name="rights"><option value="owned">Owned</option><option value="licensed">Licensed</option><option value="permission">Permission granted</option></select></label><label>Source text<textarea name="text" rows="8" maxlength="50000" required></textarea></label><button class="button">Save source and update manifest</button></form><form id="ss-mapping"><h3>Topic and outcome mapping</h3><label>Mapping JSON<textarea name="mapping" rows="12">${esc(JSON.stringify({topics:p.topics,outcomes:p.outcomes},null,2))}</textarea></label><p>Outcomes: id, text, competency (C1–C5). Topics: id, title, sourceIds and outcomes arrays. Use the saved source IDs above.</p><button class="button secondary">Save mapping</button></form><h3>Output manifest</h3>${d.manifest.outputs.map(o=>`<p><b>${esc(o.id)}</b> · ${esc(o.status)}${o.needsSourceReview?' · sources changed since this draft':''}<br>${esc(o.reason||'Instructor-authored content')}</p>`).join('')}<form id="ss-edit"><h3>Author an output draft</h3><label>Output<select name="output">${d.manifest.outputs.map(o=>`<option>${esc(o.id)}</option>`).join('')}</select></label><label>Draft text<textarea name="body" required rows="8" maxlength="30000"></textarea></label><label><input type="checkbox" name="confirm"> I confirm replacement if this output already has an instructor edit.</label><button class="button">Save versioned draft</button></form><button class="button secondary" id="ss-export">Export manifest and authored drafts</button><p>Exports omit source text. They are planning JSON, not a generated course or LMS cartridge.</p></section>`;}
document.addEventListener('change',e=>{if(e.target.id==='ss-course'){selectedCourse=e.target.value;ssCurrent=null;document.getElementById('ss-detail').innerHTML='';ssLoad();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ss-open],#ss-export');if(!b)return;try{if(b.dataset.ssOpen)ssShow(await workspaceApi('studio-sources/get',{id:b.dataset.ssOpen}));else download('studio-manifest.json',JSON.stringify(await workspaceApi('studio-sources/export',{id:ssCurrent.id}),null,2),'application/json');}catch(err){document.getElementById('ss-status').textContent=err.message;}});
document.addEventListener('submit',async e=>{if(!['ss-create','ss-source','ss-mapping','ss-edit'].includes(e.target.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),b=e.target.querySelector('button');b.disabled=true;try{const action=e.target.id.slice(3);let input=action==='create'?{title:d.title,module:Number(d.module)}:{id:ssCurrent.id,revision:ssCurrent.revision,...(action==='mapping'?JSON.parse(d.mapping):action==='edit'?{output:d.output,body:d.body,confirmOverwrite:d.confirm==='on'}:d)};const r=await workspaceApi('studio-sources/'+action,input);await ssLoad();ssShow(r.package?r:await workspaceApi('studio-sources/get',{id:r.id}));}catch(err){document.getElementById('ss-status').textContent=err.message;}finally{b.disabled=false;}});
render();
